import os, pty, sys, select, time, signal, termios, struct, fcntl, subprocess

def spawn(args, env_extra, size=(24,80), stdin_pipe=True):
    master, slave = pty.openpty()
    rows, cols = size
    # xpixel/ypixel maybe important? Set 0 initially
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, cols*8, rows*16))
    env=os.environ.copy()
    for k in ("TERM_PROGRAM","KITTY_WINDOW_ID","LC_TERMINAL","ITERM_PROFILE","ITERM_SESSION_ID"): env.pop(k,None)
    env.update(env_extra)
    def preexec():
        os.setsid()
        fcntl.ioctl(0, termios.TIOCSCTTY, 0)  # stdin? but stdin may be pipe... duh
        # Actually after dup, file descriptors: need slave to be controlling. In preexec, stdout is slave? Order: subprocess dups before preexec? Docs: preexec_fn called after fork before exec, file descriptors already duped? I think child stdio already set up.
        # Try ioctl on 1
        try:
            fcntl.ioctl(1, termios.TIOCSCTTY, 0)
        except Exception:
            pass
    if stdin_pipe:
        p=subprocess.Popen(["./executable"]+args, stdin=subprocess.PIPE, stdout=slave, stderr=slave, env=env, preexec_fn=preexec, close_fds=True)
    else:
        p=subprocess.Popen(["./executable"]+args, stdin=slave, stdout=slave, stderr=slave, env=env, preexec_fn=preexec, close_fds=True)
    os.close(slave)
    return p, master

def run(args, env_extra, actions, size=(24,80), wait=2.0, label="", stdin_pipe=True):
    p, master = spawn(args, env_extra, size, stdin_pipe)
    out=b""
    start=time.time()
    sent=[False]*len(actions)
    while time.time()-start < wait:
        for i,(delay,kind,data) in enumerate(actions):
            if not sent[i] and time.time()-start>=delay:
                try:
                    if kind=="tty":
                        os.write(master, data)
                    elif kind=="stdin":
                        p.stdin.write(data); p.stdin.flush()
                    elif kind=="close_stdin":
                        p.stdin.close()
                except Exception as e:
                    print("send err", e)
                sent[i]=True
        r,_,_=select.select([master],[],[],0.02)
        if r:
            try: chunk=os.read(master, 65536)
            except OSError: break
            if not chunk: break
            out+=chunk
        if p.poll() is not None:
            # drain
            while True:
                r,_,_=select.select([master],[],[],0.05)
                if not r: break
                try: chunk=os.read(master, 65536)
                except OSError: break
                if not chunk: break
                out+=chunk
            break
    alive=p.poll() is None
    if alive:
        try: p.kill()
        except: pass
    p.wait()
    try: os.close(master)
    except: pass
    print(f"=== {label} rc={p.returncode} alive={alive} len={len(out)}")
    print(repr(out[:6000]))
    return out, p
