import os, pty, select, time, termios, struct, fcntl, subprocess, sys

class Session:
    def __init__(self, args, env_extra, size=(24,80), xpix=640, ypix=384):
        self.master, self.slave = pty.openpty()
        fcntl.ioctl(self.slave, termios.TIOCSWINSZ, struct.pack("HHHH", size[0], size[1], xpix, ypix))
        self.stderr_r, stderr_w = os.pipe()
        env=os.environ.copy()
        for k in ("TERM_PROGRAM","KITTY_WINDOW_ID","LC_TERMINAL","ITERM_PROFILE","ITERM_SESSION_ID"): env.pop(k,None)
        env.update(env_extra)
        def preexec():
            try: os.setsid()
            except: pass
            try: fcntl.ioctl(1, termios.TIOCSCTTY, 0)
            except: pass
        self.p=subprocess.Popen(["./executable"]+args, stdin=subprocess.PIPE, stdout=self.slave, stderr=stderr_w, env=env, preexec_fn=preexec)
        os.close(self.slave); os.close(stderr_w)
        self.out=b""; self.err=b""
        self.log=[]  # (time, kind, bytes)
        self.start=time.time()
        self.responded_counts={}
    def tty_write(self, data):
        self.log.append((time.time()-self.start,"TTY-IN",data))
        os.write(self.master, data)
    def stdin_write(self, data):
        self.log.append((time.time()-self.start,"STDIN",data))
        self.p.stdin.write(data); self.p.stdin.flush()
    def pump(self, duration, responders):
        # responders: list of (trigger_bytes, response_bytes, max_times)
        end=time.time()+duration
        counts=[0]*len(responders)
        # we need to scan cumulative out+err for triggers
        scanned_out=0
        while time.time()<end:
            r,_,_=select.select([self.master,self.stderr_r],[],[],0.02)
            for fd in r:
                try: chunk=os.read(fd,65536)
                except: chunk=b""
                if not chunk: continue
                t=time.time()-self.start
                if fd==self.master:
                    self.log.append((t,"STDOUT",chunk)); self.out+=chunk
                else:
                    self.log.append((t,"STDERR",chunk)); self.err+=chunk
            # check responders against stdout (and combined)
            for i,(trig,resp,maxn) in enumerate(responders):
                if counts[i]>=maxn: continue
                # count occurrences in out
                occ=self.out.count(trig)+self.err.count(trig)
                if occ>counts[i]:
                    counts[i]+=1
                    try: self.tty_write(resp)
                    except Exception as e: self.log.append((time.time()-self.start,"ERRSEND",str(e).encode()))
            if self.p.poll() is not None:
                # drain
                for _ in range(3):
                    r,_,_=select.select([self.master,self.stderr_r],[],[],0.05)
                    if not r: break
                    for fd in r:
                        try: chunk=os.read(fd,65536)
                        except: chunk=b""
                        if fd==self.master: self.out+=chunk; self.log.append((time.time()-self.start,"STDOUT",chunk))
                        else: self.err+=chunk; self.log.append((time.time()-self.start,"STDERR",chunk))
                break
    def close(self):
        alive=self.p.poll() is None
