import os, pty, select, time, termios, struct, fcntl, subprocess
def run(resp_channel):
    # pty A stdout/ctty, pty B stdin
    mA,sA=pty.openpty(); nameA=os.ttyname(sA)
    mB,sB=pty.openpty()
    for s in (sA,sB): fcntl.ioctl(s, termios.TIOCSWINSZ, struct.pack("HHHH",24,80,640,384))
    env=os.environ.copy(); env.pop("TERM_PROGRAM",None)
    def preexec():
        try: os.setsid()
        except: pass
        try:
            fd=os.open(nameA, os.O_RDWR); fcntl.ioctl(fd, termios.TIOCSCTTY, 0)
        except: pass
    err_r,err_w=os.pipe()
    p=subprocess.Popen(["./executable","foo"], stdin=sB, stdout=sA, stderr=err_w, env=env, preexec_fn=preexec)
    os.close(sA); os.close(sB); os.close(err_w)
    out=b""; err=b""
    start=time.time(); responded={'kitty':False,'da':False,'size':False}
    while time.time()-start<1.6:
        r,_,_=select.select([mA,mB,err_r],[],[],0.02)
        for fd in r:
            try: chunk=os.read(fd,65536)
            except: chunk=b""
            if fd==mA: out+=chunk
            elif fd==err_r: err+=chunk
            elif fd==mB: out+=b"<B-echo:"+chunk+b">"
        target = mA if resp_channel=='A' else mB
        if not responded['kitty'] and b'\x1b_Gi=1' in out:
            responded['kitty']=True; os.write(target,b'\x1b_Gi=1;OK\x1b\\')
        if not responded['da'] and b'\x1b[c' in out:
            responded['da']=True; os.write(target,b'\x1b[?62;4;22c')
        if not responded['size'] and b'\x1b[14t' in out:
            responded['size']=True; os.write(target,b'\x1b[4;384;640t')
        if p.poll() is not None: break
    alive=p.poll() is None
    if alive:p.kill()
    p.wait()
    print(f"resp_channel={resp_channel} rc={p.returncode} alive={alive} out_prefix={out[:100]!r} err={err[:200]!r} responded={responded}")
run('A')
run('B')
