    if mode=='sixel':
        resp=[(b'\x1b_Gi=1,a=q,t=d,f=24\x1b\\', b'\x1b_Gi=1;OK\x1b\\',9),(b'\x1b[c', b'\x1b[?62;4;22c',9),(b'\x1b[14t', size14,9)]
        env={}
    elif mode=='kitty':
        resp=[(b'\x1b_Gi=1,a=q,t=d,f=24\x1b\\', b'\x1b_Gi=1;OK\x1b\\',9),(b'\x1b[c', b'\x1b[?62;22c',9),(b'\x1b[14t', size14,9)]
        env={}
    else:
        resp=[(b'\x1b]1337;ReportCellSize\x07', cell,9)]; env={"TERM_PROGRAM":"iTerm.app"}
    s=S(args,env,size=size,xpix=xpix,ypix=ypix,responders=resp)
