        imgs=extract_kitty(s.out); w,h,_,_,_,_,_=png_info(imgs[0][1]); info=f"PNG {w}x{h} hdr={imgs[0][0]}"
    elif mode=='iterm' and b'File=' in s.out:
        imgs=extract_iterm(s.out); w,h,_,_,_,_,_=png_info(imgs[0][1]); info=f"PNG {w}x{h} hdr={imgs[0][0]}"
