import sys
sys.path.insert(0,'/tmp')
from decode_png import png_info, extract_iterm
from collections import deque
def comps(path,color=(0,116,217,255)):
    d=open(path,'rb').read(); img=extract_iterm(d)[0][1]; w,h,ct,bd,ch,pix,bpp=png_info(img)
    def px(x,y):
        o=(y*w+x)*bpp; return tuple(pix[o:o+bpp])
    pts=set((x,y) for y in range(h) for x in range(w) if px(x,y)==color)
    out=[]
    while pts:
        seed=pts.pop(); q=deque([seed]); comp=[seed]
        while q:
            x,y=q.popleft()
            for dx in (-1,0,1):
                for dy in (-1,0,1):
                    n=(x+dx,y+dy)
                    if n in pts: pts.remove(n); q.append(n); comp.append(n)
        xs=[c[0] for c in comp]; ys=[c[1] for c in comp]
        out.append((min(xs),min(ys),max(xs),max(ys),len(comp)))
    out.sort(key=lambda c:-c[4])
    return out
if __name__=="__main__":
    for c in comps(sys.argv[1]): print(c)
