	neu.Oflag &^= syscall.OPOST
	neu.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	neu.Cflag &^= syscall.PARENB | syscall.CSIZE
	neu.Cflag |= syscall.CS8
	neu.Cc[syscall.VMIN] = 1
	neu.Cc[syscall.VTIME] = 0
	_, _, errno = syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&neu)))
	if errno != 0 {
		return old, errno
	}
	return old, nil
}

func restoreTerm(fd int, old syscall.Termios) {
	syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&old)))
}

// Write a query to stdout and read a single reply chunk, exactly the
// one-shot exchange performed by the capability probes.
func queryTerminal(query string) ([]byte, error) {
	old, err := makeRaw(int(os.Stdout.Fd()))
	if err != nil {
		return nil, err
	}
	defer restoreTerm(int(os.Stdout.Fd()), old)
	if _, err := os.Stdout.WriteString(query); err != nil {
		return nil, err
	}
	buf := make([]byte, 1024)
	n, err := os.Stdout.Read(buf)
	if err != nil {
		return nil, err
	}
	return buf[:n], nil
}

