	resp, err := queryTerminal("\x1b_Gi=1,a=q,t=d,f=24\x1b\\")
	if err != nil {
		return false
	}
	return strings.HasPrefix(string(resp), "\x1b_Gi=1")
}

func probeSixel() bool {
	resp, err := queryTerminal("\x1b[c")
	if err != nil {
		return false
	}
	s := string(resp)
	return strings.HasPrefix(s, "\x1b[?") && strings.Contains(s, ";4;")
