			n, _ := fmt.Sscanf(string(resp), "\x1b]1337;ReportCellSize=%f;%f", &ch, &cw)
			if n != 2 {
				return 0, 0, errCannotCell
			}
			cachedCellH = int(ch)
			cachedCellW = int(cw)
			cellCached = true
		}
		rows := effectiveRows(int(ws.Rows))
		return int(ws.Cols) * cachedCellW, rows * cachedCellH, nil
	case termKitty, termSixel:
		ws, err := ioctlWinsize(int(os.Stdout.Fd()))
		if err != nil {
			return 0, 0, err
		}
		if !pixelCached {
			resp, err := queryTerminal("\x1b[14t")
			if err != nil {
				return 0, 0, errCannotCell
			}
			var ph, pw int
			n, _ := fmt.Sscanf(string(resp), "\x1b[4;%d;%d", &ph, &pw)
			if n != 2 || ph <= 0 || pw <= 0 {
				return 0, 0, errCannotCell
			}
			cachedPixelW, cachedPixelH = pw, ph
			pixelCached = true
		}
		if ws.Cols == 0 || ws.Rows == 0 {
			return 0, 0, nil
		}
		cellW := cachedPixelW / int(ws.Cols)
		cellH := cachedPixelH / int(ws.Rows)
		w := cachedPixelW - cellW
		h := cachedPixelH - cellH
		if *optRows > 0 {
			h = *optRows * (h / int(ws.Rows))
		}
		return w, h, nil
	}
	return 0, 0, errCannotCell
}
