	colGrid      = color.NRGBA{179, 179, 179, 128}
	colText      = color.NRGBA{180, 180, 180, 255}
	colLegendBG  = color.NRGBA{0, 0, 0, 100}
	colMarker    = color.NRGBA{110, 127, 138, 100}
	colWhite     = color.NRGBA{255, 255, 255, 255}
)

// ---------- value formatting ----------

var siPrefixes = []string{"y", "z", "a", "f", "p", "n", "µ", "m", "", "k", "M", "G", "T", "P", "E", "Z", "Y"}

// formatSI scales a value into [1,1000) with an SI suffix, truncating
// (not rounding) to two decimal places and stripping trailing zeroes.
func formatSI(v float64) string {
	if v == 0 || math.IsNaN(v) || math.IsInf(v, 0) {
		// %v-style rendering for the special cases.
		if v == 0 {
			return "0"
		}
		return strconv.FormatFloat(v, 'g', -1, 64)
	}
	neg := v < 0
	av := math.Abs(v)
	exp := int(math.Floor(math.Log10(av) / 3))
	if exp < -8 {
		exp = -8
	}
	if exp > 8 {
		exp = 8
	}
	scaled := av / math.Pow(1000, float64(exp))
	// Guard against floating point boundary surprises.
