		exp--
	}
	trunc := math.Trunc(scaled*100) / 100
	s := strconv.FormatFloat(trunc, 'f', -1, 64)
	if neg {
		s = "-" + s
	}
	return s + siPrefixes[exp+8]
}

func formatAxis(v float64) string {
	if v != 0 && (math.Abs(v) >= 1000 || math.Abs(v) < 1) {
		return formatSI(v)
	}
	return fmt.Sprintf("%.2f", v)
}

// ---------- image drawing helpers ----------

func blend(img *image.NRGBA, x, y int, c color.NRGBA) {
	if x < 0 || y < 0 || x >= img.Bounds().Dx() || y >= img.Bounds().Dy() {
		return
	}
	if c.A == 0 {
		return
	}
	if c.A == 255 {
		img.SetNRGBA(x, y, c)
		return
	}
	d := img.NRGBAAt(x, y)
	sa := float64(c.A) / 255
	da := float64(d.A) / 255
	oa := sa + da*(1-sa)
	if oa == 0 {
		return
	}
	out := color.NRGBA{
		R: uint8((float64(c.R)*sa + float64(d.R)*da*(1-sa)) / oa),
		G: uint8((float64(c.G)*sa + float64(d.G)*da*(1-sa)) / oa),
		B: uint8((float64(c.B)*sa + float64(d.B)*da*(1-sa)) / oa),
		A: uint8(oa * 255),
	}
	img.SetNRGBA(x, y, out)
}

func fillRect(img *image.NRGBA, x0, y0, x1, y1 int, c color.NRGBA) {
	for y := y0; y <= y1; y++ {
		for x := x0; x <= x1; x++ {
			blend(img, x, y, c)
		}
	}
}

func drawText(img *image.NRGBA, x, y int, s string, c color.NRGBA) {
	cx := x
	for _, r := range s {
		if r == ' ' {
			cx += 4
			continue
		}
		g, ok := glyphs[r]
		if !ok {
			g = glyphs['?']
		}
		for row := 0; row < 7 && row < len(g); row++ {
			for col := 0; col < 5 && col < len(g[row]); col++ {
				if g[row][col] == '#' {
					blend(img, cx+col, y+row, c)
				}
			}
		}
		cx += 6
	}
}

func drawThickPoint(img *image.NRGBA, x, y int, c color.NRGBA) {
	blend(img, x, y, c)
	blend(img, x-1, y, c)
	blend(img, x, y-1, c)
	blend(img, x-1, y-1, c)
}

func drawSegment(img *image.NRGBA, x0, y0, x1, y1 float64, c color.NRGBA) {
	dx := x1 - x0
	dy := y1 - y0
	n := int(math.Max(math.Abs(dx), math.Abs(dy)) * 2)
	if n < 1 {
		n = 1
	}
