		t := float64(i) / float64(n)
		drawThickPoint(img, int(math.Round(x0+dx*t)), int(math.Round(y0+dy*t)), c)
	}
}

func drawCircle(img *image.NRGBA, cx, cy, r int, c color.NRGBA) {
