			}
		}
	}
}

// ---------- chart rendering ----------

type graphData struct {
	lineNames  []string
	linePoints [][]float64
	lineValues []float64
	markers    [][]float64
}

func renderDash(w, h int, graphs []graphData) (*image.NRGBA, error) {
	if w == 0 || h == 0 || w < 0 || h < 0 {
		return nil, fmt.Errorf("png: invalid format: invalid image size: %dx%d", w, h)
	}
	img := image.NewNRGBA(image.Rect(0, 0, w, h))
	if len(graphs) == 0 {
		return img, nil
	}
	sliceH := h / len(graphs)
	for gi, g := range graphs {
		if err := renderChart(img, gi*sliceH, sliceH, g); err != nil {
			return nil, err
		}
	}
	return img, nil
}

func renderChart(img *image.NRGBA, y0, sliceH int, g graphData) error {
	if len(g.linePoints) == 0 {
		return fmt.Errorf("please provide at least one series")
	}
	steps := len(g.linePoints[0])
	if steps == 1 {
		return fmt.Errorf("zero x-range delta; there needs to be at least (2) values")
	}
