	// Y range over line series only.
	ymin, ymax := math.Inf(1), math.Inf(-1)
	for _, pts := range g.linePoints {
		for _, v := range pts {
			if v < ymin {
				ymin = v
			}
			if v > ymax {
				ymax = v
			}
		}
	}
	if math.IsInf(ymin, 0) {
		ymin, ymax = 0, 0
	}
	if ymin == ymax {
		ymin--
		ymax++
	}

