	for i := 0; i <= nticks; i++ {
		yTicks[i] = ymin + (ymax-ymin)*float64(i)/nticks
		yLabels[i] = formatAxis(yTicks[i])
		if tw := textWidth(yLabels[i]); tw > maxLabelW {
			maxLabelW = tw
		}
	}

