	plotTop := y0 + 12
	plotBottom := y0 + sliceH - 26
	if plotBottom < plotTop+4 {
		plotBottom = plotTop + 4
	}
	plotRight := W - maxLabelW - 18
	if plotRight < plotLeft+20 {
		plotRight = plotLeft + 20
	}

	xFor := func(i int) float64 {
		return float64(plotLeft) + float64(i)/float64(steps)*(float64(plotRight-plotLeft))
	}
	yFor := func(v float64) float64 {
		return float64(plotBottom) - (v-ymin)/(ymax-ymin)*float64(plotBottom-plotTop)
	}

