	fillRect(img, plotLeft, plotTop, plotLeft+1, plotBottom, colGrid)     // left
	fillRect(img, plotRight, plotTop, plotRight+1, plotBottom, colGrid)   // right
	fillRect(img, plotLeft, plotBottom, plotRight+1, plotBottom+1, colGrid) // bottom

	// X ticks and labels.
	for i := 0; i <= nticks; i++ {
		tv := float64(steps) * float64(i) / nticks
		tx := int(math.Round(float64(plotLeft) + tv/float64(steps)*float64(plotRight-plotLeft)))
		fillRect(img, tx, plotBottom, tx+1, plotBottom+5, colGrid)
		label := fmt.Sprintf("%.2f", tv)
		drawText(img, tx-textWidth(label)/2, plotBottom+11, label, colText)
	}
	// Y ticks and labels.
	for i := 0; i <= nticks; i++ {
		ty := int(math.Round(yFor(yTicks[i])))
		fillRect(img, plotRight, ty, plotRight+5, ty+1, colGrid)
		drawText(img, plotRight+11, ty-3, yLabels[i], colText)
	}

	type pt struct{ x, y float64 }
	seriesPts := make([][]pt, len(g.linePoints))
	for si, pts := range g.linePoints {
		sp := make([]pt, len(pts))
		for i, v := range pts {
			sp[i] = pt{xFor(i), yFor(v)}
		}
		seriesPts[si] = sp
	}

	// Areas and lines.
	for si, sp := range seriesPts {
		col := seriesPalette[si%len(seriesPalette)]
		fillCol := col
		fillCol.A = 20
		// Fill under the line.
		for xi := 0; xi < len(sp)-1; xi++ {
			xa, xb := int(math.Round(sp[xi].x)), int(math.Round(sp[xi+1].x))
			if xa > xb {
				xa, xb = xb, xa
			}
			for x := xa; x <= xb; x++ {
				if x < plotLeft || x > plotRight {
					continue
				}
				// Interpolated line y at x.
				var yy float64
				if sp[xi+1].x == sp[xi].x {
					yy = sp[xi].y
				} else {
					t := (float64(x) - sp[xi].x) / (sp[xi+1].x - sp[xi].x)
					yy = sp[xi].y + t*(sp[xi+1].y-sp[xi].y)
				}
				for y := int(math.Round(yy)); y < plotBottom; y++ {
					if y >= plotTop {
						blend(img, x, y, fillCol)
					}
				}
			}
		}
		for xi := 0; xi < len(sp)-1; xi++ {
			drawSegment(img, sp[xi].x, sp[xi].y, sp[xi+1].x, sp[xi+1].y, col)
		}
	}

	// Markers: dashed vertical lines at non-zero marker points.
	for _, mpts := range g.markers {
		for i, v := range mpts {
			if v == 0 {
				continue
			}
			mx := int(math.Round(xFor(i)))
			for y := plotTop; y <= plotBottom; y++ {
				if (y-plotTop)%4 < 2 {
					blend(img, mx, y, colMarker)
					blend(img, mx+1, y, colMarker)
				}
			}
		}
	}

	// Last-value bubbles and point dots.
	for si, sp := range seriesPts {
		if len(sp) == 0 {
			continue
		}
		col := seriesPalette[si%len(seriesPalette)]
		last := sp[len(sp)-1]
		lx, ly := int(math.Round(last.x)), int(math.Round(last.y))
		drawCircle(img, lx, ly, 3, col)
		text := formatSI(g.lineValues[si])
		bw := textWidth(text) + 12
		bh := 16
		bx := lx + 8
