		for dy := 0; dy < bh; dy++ {
			frac := 1.0 - math.Abs(float64(dy)-float64(bh)/2)/float64(bh/2)
			tipW := int(8 * frac)
			for dx := 0; dx < tipW; dx++ {
				blend(img, bx-8+dx, by+dy, col)
			}
		}
		fillRect(img, bx, by, bx+bw-1, by+bh-1, col)
		drawText(img, bx+6, by+5, text, colWhite)
	}

	// Legend (top-left).
	if len(g.linePoints) > 0 {
		texts := make([]string, len(g.linePoints))
		maxTextW := 0
		for i := range g.linePoints {
			texts[i] = g.lineNames[i] + " " + formatSI(g.lineValues[i])
			if tw := textWidth(texts[i]); tw > maxTextW {
				maxTextW = tw
			}
		}
		boxX := plotLeft + 2
		boxY := y0 + 10
		lineEnd := boxX + 6 + maxTextW + 5 + 20
		boxW := (lineEnd + 10) - boxX
		boxH := len(texts)*14 + 10
		fillRect(img, boxX, boxY, boxX+boxW-1, boxY+boxH-1, colLegendBG)
		for i, txt := range texts {
			ry := boxY + i*14
			drawText(img, boxX+6, ry+5, txt, colText)
			col := seriesPalette[i%len(seriesPalette)]
			sx := boxX + 6 + textWidth(txt) + 5
			fillRect(img, sx, ry+10, lineEnd-1, ry+11, col)
		}
	}

	_ = strings.TrimSpace // keep strings import if unused in future edits
	return nil
}
