{"command":"cat > sixel.go <<'EOF'
package main

import (
	"fmt"
	"image"
	"image/color"
	"image/color/palette"
	"io"
)

// A DRCS sixel encoder.  The image is colour-reduced to the Plan 9
// palette (Floyd-Steinberg is unnecessary for a terminal chart; a
// direct palette mapping keeps the output deterministic), transparent
// pixels are left unpainted, and each six-pixel band is emitted with
// run-length encoding.

func encodeSixel(w io.Writer, img *image.NRGBA) error {
	b := img.Bounds()
	width, height := b.Dx(), b.Dy()
	if width <= 0 || height <= 0 {
		return fmt.Errorf("png: invalid format: invalid image size: %dx%d", width, height)
	}
	// Map every pixel to a palette index, -1 for transparent.
	idx := make([]int, width*height)
	used := map[int]bool{}
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			c := img.NRGBAAt(x, y)
			if c.A == 0 {
				idx[y*width+x] = -1
				continue
			}
			// Premultiply for the palette lookup, as sixel has
			// no alpha channel.
			r := int(c.R) * int(c.A) / 255
			g := int(c.G) * int(c.A) / 255
			bl := int(c.B) * int(c.A) / 255
			pi := palette.Plan9.Index(color.RGBA{uint8(r), uint8(g), uint8(bl), 255})
			idx[y*width+x] = pi
			used[pi] = true
		}
	}

	if _, err := io.WriteString(w, "\x1bP0;0;8q\"1;1"); err != nil {
		return err
	}
	// Palette definitions, ascending index.
	for pi := 0; pi < 256; pi++ {
		if !used[pi] {
			continue
		}
		c := palette.Plan9[pi]
		r, g, bl, _ := c.RGBA()
		fmt.Fprintf(w, "#%d;2;%d;%d;%d", pi, int(r>>8)*100/255, int(g>>8)*100/255, int(bl>>8)*100/255)
	}
	for band := 0; band < height; band += 6 {
		// Colors present in this band, in order of first use.
		seen := map[int]bool{}
		var order []int
		for y := band; y < band+6 && y < height; y++ {
			for x := 0; x < width; x++ {
				pi := idx[y*width+x]
				if pi >= 0 && !seen[pi] {
					seen[pi] = true
					order = append(order, pi)
				}
			}
		}
		for ci, pi := range order {
			fmt.Fprintf(w, "#%d", pi)
			x := 0
			for x < width {
				bits := byte(0)
				for dy := 0; dy < 6; dy++ {
					y := band + dy
					if y < height && idx[y*width+x] == pi {
						bits |= 1 << uint(dy)
					}
				}
				ch := bits + 63
				// Count run of the same character.
				run := 1
				for x+run < width {
					b2 := byte(0)
					for dy := 0; dy < 6; dy++ {
						y := band + dy
						if y < height && idx[y*width+x+run] == pi {
							b2 |= 1 << uint(dy)
						}
					}
					if b2 != bits {
						break
					}
					run++
				}
				if run > 3 {
					fmt.Fprintf(w, "!%d%c", run, ch)
				} else {
					for k := 0; k < run; k++ {
						fmt.Fprintf(w, "%c", ch)
					}
				}
				x += run
			}
			if ci < len(order)-1 {
				io.WriteString(w, "$")
			}
		}
		if band+6 < height {
			io.WriteString(w, "-")
		}
	}
	_, err := io.WriteString(w, "\x1b\\")
	return err
}
EOF
