	optURL      = flag.String("url", "", "URL to fetch every second. Read JSON objects from stdin if not specified.")
)

// Field is one parsed [<options>:]path element of a field spec.
type Field struct {
	Path    string
	Counter bool
	Marker  bool

	last float64
	hist []float64
}

var (
	graphs  [][]*Field
	dataMu  sync.Mutex
)

func (f *Field) add(raw float64) {
	v := raw
	if f.Counter {
		if f.last == 0 {
			f.last = v
			v = 0
		} else {
			d := v - f.last
			f.last = v
			if d < 0 {
				d = 0
			}
			v = d
		}
	}
