	if r == 0 {
		ws, err := ioctlWinsize(int(os.Stdout.Fd()))
		if err != nil {
			fatalf("jplot:  Cannot get window size:  %s", err)
		}
		r = int(ws.Rows)
	}
	fmt.Fprint(os.Stderr, strings.Repeat("\n", r))
	fmt.Fprintf(os.Stdout, "\x1b[%dA", r)
	fmt.Fprint(os.Stderr, "\x1b[s")
	preparedRows = r
	prepared = true
}

func collectGraphData() []graphData {
	dataMu.Lock()
	defer dataMu.Unlock()
	out := make([]graphData, len(graphs))
	for gi, graph := range graphs {
		var gd graphData
		for _, f := range graph {
			pts := f.points()
			xs := make([]float64, len(pts))
			for i := range xs {
				xs[i] = float64(i)
			}
			// For an empty point set (steps=0) this indexes -1,
			// reproducing the original program's failure mode.
			_ = xs[len(xs)-1]
			if f.Marker {
				gd.markers = append(gd.markers, pts)
			} else {
				last := 0.0
				if len(pts) > 0 {
					last = pts[len(pts)-1]
				}
				gd.lineNames = append(gd.lineNames, f.Path)
				gd.linePoints = append(gd.linePoints, pts)
				gd.lineValues = append(gd.lineValues, last)
			}
		}
		out[gi] = gd
	}
	return out
}

func doRender() {
	w, h, err := getImageSize()
	if err != nil {
		fatalf("jplot:  Cannot get window size:  %s", err)
	}
	img, err := renderDash(w, h, collectGraphData())
	if err != nil {
		fatalf("jplot:  cannot render graph: %s", err)
	}
	switch detectedTerm {
	case termITerm, termKitty:
		var buf bytes.Buffer
		if err := png.Encode(&buf, img); err != nil {
