				fmt.Fprintf(os.Stdout, "\x1b_Ga=d,d=i,i=%d,q=2\x1b\\", kittyPrevID)
			}
			kittyPrevID = kittyImageID
			kittyHasPrev = true
			kittyImageID = 3 - kittyImageID
		}
	case termSixel:
		if err := encodeSixel(os.Stdout, img); err != nil {
			fatalf("jplot:  cannot render graph: %s", err)
		}
	}
}

func renderFrame() {
	if !prepared {
		prepare()
	} else {
		fmt.Fprint(os.Stderr, "\x1b[s")
	}
	doRender()
	fmt.Fprint(os.Stderr, "\x1b[u")
}

func teardown() {
	fmt.Fprint(os.Stderr, "\x1b[?25h")
	fmt.Fprintf(os.Stdout, "\x1b[%dB", preparedRows)
	fmt.Fprint(os.Stderr, "\n")
}

// ---- data sources ----

func runStdin(errCh chan<- error, doneCh chan<- struct{}) {
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		var obj interface{}
		if err := json.Unmarshal(scanner.Bytes(), &obj); err != nil {
			errCh <- fmt.Errorf("input error: %w", err)
			return
		}
		if err := addObject(obj); err != nil {
			errCh <- err
			return
		}
	}
	if err := scanner.Err(); err != nil {
		errCh <- fmt.Errorf("input error: %w", err)
		return
	}
	close(doneCh)
}

func fetchHTTP() error {
	resp, err := http.Get(*optURL)
	if err != nil {
		return fmt.Errorf("input error: %w", err)
	}
	body, err := io.ReadAll(resp.Body)
	resp.Body.Close()
	if err != nil {
		return fmt.Errorf("input error: %w", err)
	}
	var obj interface{}
	if err := json.Unmarshal(body, &obj); err != nil {
		return fmt.Errorf("input error: %w", err)
	}
	return addObject(obj)
}

func runHTTP(errCh chan<- error) {
	ticker := time.NewTicker(*optInterval)
	for {
		if err := fetchHTTP(); err != nil {
			errCh <- err
			return
		}
		<-ticker.C
	}
}

func usage() {
	out := flag.CommandLine.Output()
	fmt.Fprint(out, "Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]:\n\nOPTIONS:\n")
	flag.PrintDefaults()
	fmt.Fprint(out, "\nFIELD_SPEC: [<option>[,<option>...]:]path\n  option:\n    - counter: Computes the difference with the last value. The value must increase monotonically.\n    - marker: When the value is none-zero, a vertical line is drawn.\n  path:\n    JSON field path (eg: field.sub-field).\n")
}

func main() {
	detectedTerm = detectTerminal()
	swallowSignals()
	flag.Usage = usage
	flag.Parse()

	if detectedTerm == termNone {
		fatalf("jplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
	}
	if flag.NArg() == 0 {
		flag.Usage()
		os.Exit(1)
	}
	parsed, badOpt, ok := parseSpecs(flag.Args())
	if !ok {
		fatalf("jplot:  Cannot parse spec:  invalid field option: %s", badOpt)
	}
	graphs = parsed

	errCh := make(chan error, 1)
	doneCh := make(chan struct{})
	if *optURL != "" {
		go runHTTP(errCh)
	} else {
		if stdinIsTerminal() {
			fatalf("jplot:  neither --url nor stdin is provided")
		}
		go runStdin(errCh, doneCh)
	}

	ticker := time.NewTicker(time.Second)
	for {
		select {
		case err := <-errCh:
			fatalf("jplot:  Data source error:  %s", err)
		case <-doneCh:
			if !prepared {
				doRender()
			} else {
				teardown()
			}
			return
		case <-ticker.C:
			renderFrame()
		}
	}
}
