package main

import (
	"bufio"
	"encoding/base64"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
	"sync"
	"time"
	"bytes"
	"image/png"
)

var (
	optInterval = flag.Duration("interval", time.Second, "When url is provided, defines the interval between fetches. Note that counter fields are computed based on this interval.")
	optRows     = flag.Int("rows", 0, "Limits the height of the graph output.")
	optSteps    = flag.Int("steps", 100, "Number of values to plot.")
	optURL      = flag.String("url", "", "URL to fetch every second. Read JSON objects from stdin if not specified.")
)

// Field is one parsed [<options>:]path element of a field spec.
type Field struct {
	Path    string
	Counter bool
	Marker  bool

	last float64
	hist []float64
}

var (
	graphs  [][]*Field
	dataMu  sync.Mutex
)

func (f *Field) add(raw float64) {
	v := raw
	if f.Counter {
		if f.last == 0 {
			f.last = v
			v = 0
		} else {
			d := v - f.last
			f.last = v
			if d < 0 {
				d = 0
			}
			v = d
		}
	}
	f.hist = append(f.hist, v)
	if *optSteps > 0 && len(f.hist) > *optSteps {
		f.hist = f.hist[len(f.hist)-*optSteps:]
	}
}

func (f *Field) points() []float64 {
	out := make([]float64, *optSteps)
	if *optSteps > 0 && len(f.hist) > 0 {
		n := len(f.hist)
		if n > *optSteps {
			n = *optSteps
		}
		copy(out[*optSteps-n:], f.hist[len(f.hist)-n:])
	}
	return out
}

func extract(obj interface{}, path string) (float64, error) {
	cur := obj
	for _, key := range strings.Split(path, ".") {
		m, ok := cur.(map[string]interface{})
		if !ok {
			return 0, fmt.Errorf("cannot get %s: %s is not an object. map[]", path, key)
		}
		val, ok := m[key]
		if !ok {
			return 0, fmt.Errorf("cannot get %s: %s does not exist.", path, key)
		}
		cur = val
	}
	if fv, ok := cur.(float64); ok {
		return fv, nil
	}
	return 0, fmt.Errorf("invalid type %s: %T", path, cur)
}

func addObject(obj interface{}) error {
	dataMu.Lock()
	defer dataMu.Unlock()
	for _, graph := range graphs {
		for _, f := range graph {
			v, err := extract(obj, f.Path)
			if err != nil {
				return err
			}
			f.add(v)
		}
	}
	return nil
}

func parseSpecs(args []string) ([][]*Field, string, bool) {
	var out [][]*Field
	for _, arg := range args {
		var graph []*Field
		for _, fs := range strings.Split(arg, "+") {
			f := &Field{}
			if idx := strings.Index(fs, ":"); idx >= 0 {
				for _, op := range strings.Split(fs[:idx], ",") {
					switch op {
					case "counter":
						f.Counter = true
					case "marker":
						f.Marker = true
					default:
						return nil, op, false
					}
				}
				f.Path = fs[idx+1:]
			} else {
				f.Path = fs
			}
			graph = append(graph, f)
		}
		out = append(out, graph)
	}
	return out, "", true
}

// ---- fatal helpers (all fatal program messages go to stdout) ----

func fatalf(format string, args ...interface{}) {
	fmt.Fprintf(os.Stdout, format+"\n", args...)
	os.Exit(1)
}

// ---- rendering pipeline ----

var (
	prepared     bool
	preparedRows int
)

func prepare() {
	fmt.Fprint(os.Stderr, "\x1b[?25l")
	r := *optRows
	if r == 0 {
		ws, err := ioctlWinsize(int(os.Stdout.Fd()))
		if err != nil {
			fatalf("jplot:  Cannot get window size:  %s", err)
		}
		r = int(ws.Rows)
	}
	fmt.Fprint(os.Stderr, strings.Repeat("\n", r))
	fmt.Fprintf(os.Stdout, "\x1b[%dA", r)
	fmt.Fprint(os.Stderr, "\x1b[s")
	preparedRows = r
	prepared = true
}

func collectGraphData() []graphData {
	dataMu.Lock()
	defer dataMu.Unlock()
	out := make([]graphData, len(graphs))
	for gi, graph := range graphs {
		var gd graphData
		for _, f := range graph {
			pts := f.points()
			xs := make([]float64, len(pts))
			for i := range xs {
				xs[i] = float64(i)
			}
			// For an empty point set (steps=0) this indexes -1,
			// reproducing the original program's failure mode.
			_ = xs[len(xs)-1]
			if f.Marker {
				gd.markers = append(gd.markers, pts)
			} else {
				last := 0.0
				if len(pts) > 0 {
					last = pts[len(pts)-1]
				}
				gd.lineNames = append(gd.lineNames, f.Path)
				gd.linePoints = append(gd.linePoints, pts)
				gd.lineValues = append(gd.lineValues, last)
			}
		}
		out[gi] = gd
	}
	return out
}

func doRender() {
	w, h, err := getImageSize()
	if err != nil {
		fatalf("jplot:  Cannot get window size:  %s", err)
	}
	img, err := renderDash(w, h, collectGraphData())
	if err != nil {
		fatalf("jplot:  cannot render graph: %s", err)
	}
	switch detectedTerm {
	case termITerm, termKitty:
		var buf bytes.Buffer
		if err := png.Encode(&buf, img); err != nil {
			fatalf("jplot:  cannot render graph: %s", err)
		}
		if detectedTerm == termITerm {
			fmt.Fprintf(os.Stdout, "\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\x07", w, h, base64.StdEncoding.EncodeToString(buf.Bytes()))
		} else {
			fmt.Fprintf(os.Stdout, "\x1b_Ga=T,f=100,t=d,i=%d,X=0,Y=0,q=2;%s\x1b\\", kittyImageID, base64.StdEncoding.EncodeToString(buf.Bytes()))
			if kittyHasPrev {
				fmt.Fprintf(os.Stdout, "\x1b_Ga=d,d=i,i=%d,q=2\x1b\\", kittyPrevID)
			}
			kittyPrevID = kittyImageID
			kittyHasPrev = true
			kittyImageID = 3 - kittyImageID
		}
	case termSixel:
		if err := encodeSixel(os.Stdout, img); err != nil {
			fatalf("jplot:  cannot render graph: %s", err)
		}
	}
}

func renderFrame() {
	if !prepared {
		prepare()
	} else {
		fmt.Fprint(os.Stderr, "\x1b[s")
	}
	doRender()
	fmt.Fprint(os.Stderr, "\x1b[u")
}

func teardown() {
	fmt.Fprint(os.Stderr, "\x1b[?25h")
	fmt.Fprintf(os.Stdout, "\x1b[%dB", preparedRows)
	fmt.Fprint(os.Stderr, "\n")
}

// ---- data sources ----

func runStdin(errCh chan<- error, doneCh chan<- struct{}) {
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		var obj interface{}
		if err := json.Unmarshal(scanner.Bytes(), &obj); err != nil {
			errCh <- fmt.Errorf("input error: %w", err)
			return
		}
		if err := addObject(obj); err != nil {
			errCh <- err
			return
		}
	}
	if err := scanner.Err(); err != nil {
		errCh <- fmt.Errorf("input error: %w", err)
		return
	}
	close(doneCh)
}

func fetchHTTP() error {
	resp, err := http.Get(*optURL)
	if err != nil {
		return fmt.Errorf("input error: %w", err)
	}
	body, err := io.ReadAll(resp.Body)
	resp.Body.Close()
	if err != nil {
		return fmt.Errorf("input error: %w", err)
	}
	var obj interface{}
	if err := json.Unmarshal(body, &obj); err != nil {
		return fmt.Errorf("input error: %w", err)
	}
	return addObject(obj)
}

func runHTTP(errCh chan<- error) {
	ticker := time.NewTicker(*optInterval)
	for {
		if err := fetchHTTP(); err != nil {
			errCh <- err
			return
		}
		<-ticker.C
	}
}

func usage() {
	out := flag.CommandLine.Output()
	fmt.Fprint(out, "Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]:\n\nOPTIONS:\n")
	flag.PrintDefaults()
	fmt.Fprint(out, "\nFIELD_SPEC: [<option>[,<option>...]:]path\n  option:\n    - counter: Computes the difference with the last value. The value must increase monotonically.\n    - marker: When the value is none-zero, a vertical line is drawn.\n  path:\n    JSON field path (eg: field.sub-field).\n")
}

func main() {
	detectedTerm = detectTerminal()
	swallowSignals()
	flag.Usage = usage
	flag.Parse()

	if detectedTerm == termNone {
		fatalf("jplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
	}
	if flag.NArg() == 0 {
		flag.Usage()
		os.Exit(1)
	}
	parsed, badOpt, ok := parseSpecs(flag.Args())
	if !ok {
		fatalf("jplot:  Cannot parse spec:  invalid field option: %s", badOpt)
	}
	graphs = parsed

	errCh := make(chan error, 1)
	doneCh := make(chan struct{})
	if *optURL != "" {
		go runHTTP(errCh)
	} else {
		if stdinIsTerminal() {
			fatalf("jplot:  neither --url nor stdin is provided")
		}
		go runStdin(errCh, doneCh)
	}

	ticker := time.NewTicker(time.Second)
	for {
		select {
		case err := <-errCh:
			fatalf("jplot:  Data source error:  %s", err)
		case <-doneCh:
			if !prepared {
				doRender()
			} else {
				teardown()
			}
			return
		case <-ticker.C:
			renderFrame()
		}
	}
}
